import hashlib,json,runpy,subprocess,sys
from pathlib import Path
import pytest
root,source,observer,event,mode,*arguments=sys.argv[1:]
Observer=runpy.run_path(observer)['Observer']
class Measurement(Observer):
 def pytest_sessionfinish(self,session,exitstatus):
  origins={}
  for name in ['polisyos.scientist.methods.autotune.pareto','polisyos.scientist.methods.autotune.models','polisyos.core.artifacts.store','polisyos.core.canon.canon_json']:
   path=Path(sys.modules[name].__file__).resolve()
   relative=path.relative_to(root).as_posix()
   data=subprocess.check_output(['git','show',source+':'+relative],cwd=root)
   origins[name]={'path':str(path),'git_path':relative,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'git_match':data==path.read_bytes()}
   assert origins[name]['git_match']
  self.emit('session_finish',exitstatus=int(exitstatus),native_origins=origins)
if mode=='remove_property':
 from polisyos.scientist.methods.autotune.pareto import ParetoPromoter
 original=ParetoPromoter._assess_objective_vector
 def replace_unusable_with_zero(self,evaluation):
  vector,missing,nonfinite=original(self,evaluation)
  return (tuple(0.0 for _ in self._policies),[],[]) if vector is None else (vector,missing,nonfinite)
 ParetoPromoter._assess_objective_vector=replace_unusable_with_zero
 print('PROPERTY_REMOVAL: unusable required coordinates become zero; metadata, strict CAS reader and tests unchanged',flush=True)
raise SystemExit(pytest.main(arguments,plugins=[Measurement(event)]))
